contentRule.content:
@js:
  let dl=result.match(/https:\/\/play.*?\.m3u8/)
  url=result.match(/https.*?\.m3u8/)
  furl=result.match(/https:\/\/fq.*?\.m3u8/)
  if (furl){
    java.startBrowser(furl,chapter.title)
    java.toast('\n正在加载视频，请耐心等候')
    ' 【刷新正文】或【点击章节链接】跳转播放\n🔗播放链接:\n'+furl}
  	else if (dl){
  		java.startBrowser(baseUrl,chapter.title)
  		java.toast('\n正在加载网页，请耐心等候')
    ' 【请点击章节链接观看】或【下载后观看】\n🔗下载链接:\n'+dl}
  else if (url){
    java.startBrowser(url,chapter.title)
    java.toast('\n正在加载视频，请耐心等候')
    ' 【刷新正文】或【点击章节链接】跳转播放\n🔗播放链接:\n'+url}
  else{
	  pics=java.getString('.prose@img@src')
	  p=String(pics).split("\n").map(i=>`<img src="${i}">`).join("\n");
    p;}

