ruleToc.chapterList:
@js:
list=[]
JSON.parse(result).map([x,title,cid]=>{
	if(x=="dt"){
		text= "🏮〖"+title+"〗🏮";
		if(cid){
			cid=cid;
			url =	baseUrl.replace(/dir\.json.*/,cid+'.html');}
		else{ cid=""; url=""; }				
	  info= title;
list.push({	
	 text: text,
	 href: url,
	 cid: cid,
		volume: true})
		}
  else if(x=="dd"){
   	url =	baseUrl.replace(/dir\.json.*/,cid+'.html');	
   	try{info=info;}catch(e){info=""; }		 
list.push({	
	text: title,
	 href: url,
	 cid: cid,
   info: info
	 })
		}  
})
list

